int process_ticket_reply(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void *buf, void *end) {
    int ret;
    int num_tickets;
    int version;

    if ((ret = ceph_decode_version(&version, buf, end)) < 0) {
        return ret;
    }

    if ((ret = ceph_decode_num(&num_tickets, buf, end)) < 0) {
        return ret;
    }

    for (int i = 0; i < num_tickets; i++) {
        ret = process_one_ticket(ac, secret, buf, end);
        if (ret < 0) {
            return ret;
        }
    }

    return 0;
}

int process_ticket_reply(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void *buf, void *end)
{
    int version;
    int num_tickets;
    int ret;
    void *p = buf;

    if (p + sizeof(version) > end)
        return -EINVAL;

    version = ceph_decode_version(&p);
    if (version != 1) {
        return -EINVAL;
    }

    if (p + sizeof(num_tickets) > end)
        return -EINVAL;

    num_tickets = ceph_decode_32(&p);
    if (num_tickets < 0)
        return num_tickets;

    while (num_tickets > 0) {
        ret = process_one_ticket(ac, secret, p, end);
        if (ret < 0)
            return ret;

        p += ret;
        num_tickets--;
    }

    return 0;
}

int process_ticket_reply(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void *buf, void *end) {
    int version;
    int num_tickets;
    int i;
    int ret;

    if ((void *)&version >= end) {
        return -EINVAL;
    }
    version = *(int *)buf;
    buf = (void *)((int *)buf + 1);

    if ((void *)&num_tickets >= end) {
        return -EINVAL;
    }
    num_tickets = *(int *)buf;
    buf = (void *)((int *)buf + 1);

    if (version < 1 || version > CEPH_AUTH_SUPPORTED_VERSION) {
        return -EINVAL;
    }

    for (i = 0; i < num_tickets; i++) {
        ret = process_one_ticket(ac, secret, buf, end);
        if (ret < 0) {
            return ret;
        }
        buf = (void *)((char *)buf + ret);
    }

    return 0;
}

int ceph_auth_client_process_ticket_reply(struct ceph_auth_client *ac,
                                          struct ceph_crypto_key *secret,
                                          void *buf, void *end)
{
  int version, num_tickets, i, ret;
  void *p = buf;

  if (p + sizeof(version) > end)
    return -EINVAL;

  version = *(int *)p;
  p += sizeof(version);

  if (version != 1) {
    return -EINVAL;
  }

  if (p + sizeof(num_tickets) > end)
    return -EINVAL;

  num_tickets = *(int *)p;
  p += sizeof(num_tickets);

  for (i = 0; i < num_tickets; i++) {
    ret = process_one_ticket(ac, secret, &p, end);
    if (ret < 0)
      return ret;
  }

  return 0;
}

int ceph_process_ticket_reply(struct ceph_auth_client *ac,
                              struct ceph_crypto_key *secret,
                              void *buf, void *end)
{
    int ret = 0;
    int version, num_tickets;
    void **p = &buf;

    if (end - *p < sizeof(version)) {
        return -EINVAL;
    }
    version = le32_to_cpu(*(__le32 *)*p);
    *p += sizeof(version);

    if (version != 1) {
        return -EINVAL;
    }

    if (end - *p < sizeof(num_tickets)) {
        return -EINVAL;
    }
    num_tickets = le32_to_cpu(*(__le32 *)*p);
    *p += sizeof(num_tickets);

    for (int i = 0; i < num_tickets; i++) {
        ret = process_one_ticket(ac, secret, p, end);
        if (ret < 0) {
            return ret;
        }
    }

    return 0;
}
